"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import AuthGate from "@/components/auth-gate";
import { api } from "@/lib/api";
import { formatMoney } from "@/lib/money";
import { Spinner } from "@/components/ui/spinner";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

interface OrderSummary {
  id: string;
  number: number;
  createdAt: string;
  status: string;
  payment: string;
  totalCents: number;
  currency: string;
  itemCount: number;
  openComplaints: number;
}

interface Page<T> {
  items: T[];
  total: number;
  page: number;
  perPage: number;
  totalPages: number;
}

function statusBadge(s: string) {
  const map: Record<string, string> = {
    PENDING_PAYMENT: "bg-yellow-500/10 text-yellow-600",
    PAID: "bg-green-500/10 text-green-600",
    FULFILLED: "bg-blue-500/10 text-blue-600",
    CANCELLED: "bg-muted text-muted-foreground",
    REFUNDED: "bg-muted text-muted-foreground",
  };
  return map[s] || "bg-muted text-muted-foreground";
}

function OrdersPage() {
  const [data, setData] = useState<Page<OrderSummary> | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        const res = await api<Page<OrderSummary>>("/orders");
        setData(res.data);
      } catch (e) {
      } finally {
        setLoading(false);
      }
    };
    void load();
  }, []);

  if (loading) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <Spinner className="size-6" />
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-4xl p-6">
      <h1 className="mb-6 text-3xl font-bold">My orders</h1>
      {data?.items.length === 0 ? (
        <Card>
          <CardContent className="py-12 text-center">
            <p className="text-muted-foreground">No orders yet</p>
            <Button asChild className="mt-4">
              <Link href="/marketplace">Shop now</Link>
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-4">
          {data?.items.map((o) => (
            <Card key={o.id}>
              <CardHeader className="flex flex-row items-center justify-between">
                <div>
                  <CardTitle>Order #{o.number}</CardTitle>
                  <p className="text-sm text-muted-foreground">
                    {new Date(o.createdAt).toLocaleString()}
                  </p>
                </div>
                <div className="flex items-center gap-2">
                  <Badge className={statusBadge(o.status)}>{o.status}</Badge>
                  <Badge variant="outline">{o.payment}</Badge>
                </div>
              </CardHeader>
              <CardContent className="flex items-center justify-between">
                <div className="text-sm text-muted-foreground">
                  {o.itemCount} item{o.itemCount === 1 ? "" : "s"}
                  {o.openComplaints > 0 && (
                    <span className="ml-2 text-amber-600">
                      {o.openComplaints} open complaint
                      {o.openComplaints === 1 ? "" : "s"}
                    </span>
                  )}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

export default function OrdersRoute() {
  return (
    <AuthGate>
      <OrdersPage />
    </AuthGate>
  );
}
